= MAKE CODE:
// A stepper on an A4988 driver (STEP on pin 3, DIR on pin 2)
// Moves 800 steps forward and back again, with smooth acceleration.
// Wiring: STEP -> pin 3, DIR -> pin 2, EN -> pin 4 (LOW = enabled),
//         driver VMOT to the motor supply (12-24 V, 100 uF across it), GND shared.
// Set the driver's current limit (Vref) for your motor before running it.
// Steps per turn = 200 (a 1.8 degree motor) x microsteps (MS pins / driver default).
#include <AccelStepper.h>

const int stepPin = 3;
const int dirPin = 2;
const int enablePin = 4;
const long stepsPerTurn = 200L * 8;   // 1/8 microstepping

= MAKE CODE:
// Motor start/stop with a seal-in: Start (NO) OR the motor's own contact,
// in series with Stop (NC, so XIC: TRUE while not pressed) and the overload
// Run light follows the motor
[XIC(StartPB) ,XIC(Motor) ]XIC(StopPB)XIC(OverloadOK)OTE(Motor);
XIC(Motor)OTE(RunLight);
END
